\pi (12)^2 (24) - (2)(1/3)\pi (12)^2(12) &= 12^3\pi(2-2/3)\\
&=12^3\pi(4/3)\\
&=2304\pi \text{ cubic cm}.
\end{align*}

\boxed{2304\pi}

